import Foundation
import XCTest
@testable import ScionicMerkleTree

/// The nine cross-language spec-vector assertions.
///
/// The corpus -- DAGs, partials, transmission packets, batched packets, broken
/// DAGs and the input trees they were built from -- is generated by the Go repo's
/// `tools/specvectors` and COMMITTED into this repository under `spec/vectors`.
/// Go, Swift and Rust each run these same nine assertions against their own copy.
///
/// It is committed, and a missing corpus fails hard, because of what this file
/// used to do: it resolved `spec/vectors` from a sibling `scionic-merkletree`
/// checkout and called `XCTSkip` when that was absent. It was absent on every
/// machine. These tests skipped for four releases and the suite reported green the
/// whole time, because a skip is not a failure. Checking nothing is not the same
/// as having nothing to check, and only one of those should be silent.
///
/// Every artifact is committed TWICE, once as `.cbor` and once as `.json` at the
/// same path. That half is newer than the rest, and Swift is one of the two ports
/// it caught -- see `testManifestJSONMatchesTheCommittedBytes`.
final class SpecVectorParityTests: XCTestCase {
    private struct VectorManifest: Decodable {
        struct MetadataEntry: Decodable {
            let key: String
            let value: String
        }

        struct NegativeVector: Decodable {
            let path: String
            let pathJSON: String
            let kind: String
            let description: String

            enum CodingKeys: String, CodingKey {
                case path
                case pathJSON = "path_json"
                case kind
                case description
            }
        }

        struct VectorCase: Decodable {
            let name: String
            let rootKind: String
            let rootInputPath: String
            let rootHash: String
            let additionalData: [MetadataEntry]
            let leafCount: Int
            let fileLeaves: Int
            let directoryLeaves: Int
            let chunkLeaves: Int
            let fullDag: String
            let fullDagJSON: String
            let partialDags: [String]
            let partialDagsJSON: [String]
            let transmissionPackets: [String]
            let transmissionPacketsJSON: [String]
            let batchedPackets: [String]
            let batchedPacketsJSON: [String]
            let negativeVectors: [NegativeVector]

            /// The root metadata this case was BUILT with. It is part of the root
            /// CID preimage, so a rebuild that ignores it lands on a different
            /// root. The manifest carries it as a sorted list rather than an
            /// object because the manifest's own CBOR encoder does not sort map
            /// keys, and a manifest that cannot reproduce its own bytes would
            /// undermine every byte comparison below it.
            var rootMetadata: [String: String] {
                Dictionary(uniqueKeysWithValues: additionalData.map { ($0.key, $0.value) })
            }

            enum CodingKeys: String, CodingKey {
                case name
                case rootKind = "root_kind"
                case rootInputPath = "root_input_path"
                case rootHash = "root_hash"
                case additionalData = "additional_data"
                case leafCount = "leaf_count"
                case fileLeaves = "file_leaves"
                case directoryLeaves = "directory_leaves"
                case chunkLeaves = "chunk_leaves"
                case fullDag = "full_dag"
                case fullDagJSON = "full_dag_json"
                case partialDags = "partial_dags"
                case partialDagsJSON = "partial_dags_json"
                case transmissionPackets = "transmission_packets"
                case transmissionPacketsJSON = "transmission_packets_json"
                case batchedPackets = "batched_packets"
                case batchedPacketsJSON = "batched_packets_json"
                case negativeVectors = "negative_vectors"
            }
        }

        let chunkSize: Int
        let batchSize: Int
        let cases: [VectorCase]

        enum CodingKeys: String, CodingKey {
            case chunkSize = "chunk_size"
            case batchSize = "batch_size"
            case cases
        }
    }

    private struct CorpusMissing: Error, CustomStringConvertible {
        let path: String
        var description: String {
            """
            Spec-vector corpus missing at \(path).
            It is committed to this repository; regenerate it from the Go repo with:
              go run ./tools/specvectors -out ../Scionic-MerkleTree-Swift/spec/vectors
            """
        }
    }

    /// This repository's own committed corpus, resolved from this file's location
    /// rather than the runner's working directory so it works under both
    /// `swift test` and Xcode.
    ///
    /// #filePath = <swift repo>/tests/tests/SpecVectorParityTests.swift
    private static let vectorsRoot: String = {
        let repoRoot = (((#filePath as NSString)
            .deletingLastPathComponent as NSString)
            .deletingLastPathComponent as NSString)
            .deletingLastPathComponent
        return (repoRoot as NSString).appendingPathComponent("spec/vectors")
    }()

    private func loadedManifest() throws -> VectorManifest {
        let manifestPath = (Self.vectorsRoot as NSString).appendingPathComponent("manifest.json")
        guard FileManager.default.fileExists(atPath: manifestPath) else {
            throw CorpusMissing(path: manifestPath)
        }
        let data = try Data(contentsOf: URL(fileURLWithPath: manifestPath))
        let manifest = try JSONDecoder().decode(VectorManifest.self, from: data)
        XCTAssertFalse(
            manifest.cases.isEmpty,
            "the manifest lists no cases; every assertion below would pass vacuously"
        )
        return manifest
    }

    private func vectorPath(_ relativePath: String) -> String {
        (Self.vectorsRoot as NSString).appendingPathComponent(relativePath)
    }

    private func readVector(_ relativePath: String) throws -> Data {
        try Data(contentsOf: URL(fileURLWithPath: vectorPath(relativePath)))
    }

    private func assertShape(
        _ label: String,
        _ dag: Dag,
        _ vectorCase: VectorManifest.VectorCase
    ) {
        XCTAssertEqual(dag.root, vectorCase.rootHash, "\(label): root CID")
        XCTAssertEqual(dag.leafs.count, vectorCase.leafCount, "\(label): leaf count")
        XCTAssertEqual(
            dag.leafs.values.filter { $0.type == .file }.count,
            vectorCase.fileLeaves,
            "\(label): file leaves"
        )
        XCTAssertEqual(
            dag.leafs.values.filter { $0.type == .directory }.count,
            vectorCase.directoryLeaves,
            "\(label): directory leaves"
        )
        XCTAssertEqual(
            dag.leafs.values.filter { $0.type == .chunk }.count,
            vectorCase.chunkLeaves,
            "\(label): chunk leaves"
        )
    }

    func testManifestFullDagVectorsParseAndVerify() throws {
        for vectorCase in try loadedManifest().cases {
            let dag = try Dag.readDag(path: vectorPath(vectorCase.fullDag))
            assertShape(vectorCase.name, dag, vectorCase)
            try dag.verify()
        }
    }

    /// Encoding the same DAG twice must produce the same bytes.
    ///
    /// Not a theoretical property. Go's default CBOR encoder sorted nothing, so its
    /// maps encoded in Go's randomized iteration order, and generating this corpus
    /// three times produced three different `dag.cbor` files for identical input.
    /// Nothing was corrupted -- a CID comes from leaf fields, not from this
    /// envelope, and CBOR maps are unordered to any decoder -- but it made the
    /// serialized form unusable as an identity: not diffable, not cacheable, not
    /// dedupable.
    ///
    /// Swift is the port most exposed to this, because `Dictionary` iteration order
    /// is not merely unspecified but per-process randomized by seeded hashing.
    func testManifestFullDagCBORIsDeterministic() throws {
        for vectorCase in try loadedManifest().cases {
            let committed = try readVector(vectorCase.fullDag)
            let dag = try Dag.fromCBOR(committed)

            let first = dag.toCBOR()
            let second = dag.toCBOR()

            // Cross-port byte parity: Swift must reproduce, byte for byte, the
            // envelope Go committed. This is strictly stronger than encoding the
            // same DAG twice -- a port could be perfectly self-consistent and
            // still disagree with Go on field order.
            XCTAssertEqual(
                first, committed,
                "\(vectorCase.name): re-encoded DAG differs from the bytes Go committed"
            )
            XCTAssertEqual(
                first, second,
                "\(vectorCase.name): encoding the same DAG twice produced different bytes"
            )

            let roundTripped = try Dag.fromCBOR(first)
            assertShape("\(vectorCase.name) (round trip)", roundTripped, vectorCase)
            try roundTripped.verify()
        }
    }

    /// The only assertion here that exercises DAG construction rather than
    /// decoding: rebuild each DAG from the committed input tree and require the same
    /// root CID. This is what makes the corpus a spec rather than a snapshot -- a
    /// port can only pass by chunking, naming, sorting and hashing exactly the way
    /// Go does.
    func testManifestInputRootsMatchGoVectors() throws {
        let manifest = try loadedManifest()
        setChunkSize(manifest.chunkSize)
        defer { setDefaultChunkSize() }

        for vectorCase in manifest.cases {
            let caseRoot = vectorPath("cases/\(vectorCase.name)")
            let inputPath = (caseRoot as NSString).appendingPathComponent(vectorCase.rootInputPath)
            // Additional data is part of the root CID preimage, so a rebuild that
            // ignores it lands on a different root. Only json_metadata_probe
            // carries any, and the no-metadata path stays on createDag rather than
            // assuming an empty dictionary is identical to none.
            let rebuilt = vectorCase.additionalData.isEmpty
                ? try ScionicMerkleTree.createDag(path: inputPath, timestampRoot: false)
                : try createDagAdvanced(path: inputPath, additionalData: vectorCase.rootMetadata)
            assertShape("\(vectorCase.name) (rebuilt)", rebuilt, vectorCase)
            try rebuilt.verify()
        }
    }

    func testManifestPartialVectorsParseAndVerify() throws {
        var checked = 0
        var genuinelyPartial = 0
        for vectorCase in try loadedManifest().cases {
            for partialPath in vectorCase.partialDags {
                let partial = try Dag.readDag(path: vectorPath(partialPath))
                XCTAssertEqual(
                    partial.root, vectorCase.rootHash,
                    "\(vectorCase.name): \(partialPath) root"
                )
                try partial.verify()
                checked += 1
                if partial.isPartial() {
                    genuinelyPartial += 1
                }
            }
        }
        XCTAssertGreaterThan(checked, 0, "no partial vectors in the corpus")
        // Not every partial vector is partial: single_small_file holds exactly one
        // file, so requesting it returns the whole DAG and isPartial() is correctly
        // false. What must hold is that SOME vector takes the proof-carrying path,
        // otherwise this test is re-testing full-DAG verification under another name.
        XCTAssertGreaterThan(
            genuinelyPartial, 0,
            "no vector in the corpus verifies through the partial-DAG proof path"
        )
    }

    /// Pins the half of the contract the positive vectors cannot: a port that
    /// accepted everything would pass every other test in this file.
    ///
    /// The assertion is deliberately "decode or verify must fail", not "the error
    /// message contains X". Each port has its own error vocabulary, and requiring a
    /// shared substring would assert that three independent enums agree on wording
    /// -- a requirement no user has, and one satisfiable by editing a string.
    func testManifestNegativeVectorsFailVerification() throws {
        var checked = 0
        for vectorCase in try loadedManifest().cases {
            for negative in vectorCase.negativeVectors {
                // Both encodings of the same broken DAG must be rejected. Checking
                // only CBOR would leave room for a lenient JSON path -- and the
                // JSON path is the one that went four releases with no cross-port
                // test at all.
                let committedCBOR = try readVector(negative.path)
                let committedJSON = try readVector(negative.pathJSON)
                XCTAssertFalse(
                    decodesAndVerifies { try Dag.fromCBOR(committedCBOR) },
                    "\(vectorCase.name): negative vector '\(negative.kind)' was accepted as CBOR (\(negative.description))"
                )
                XCTAssertFalse(
                    decodesAndVerifies { try Dag.fromJSON(committedJSON) },
                    "\(vectorCase.name): negative vector '\(negative.kind)' was accepted as JSON (\(negative.description))"
                )
                checked += 2
            }
        }
        XCTAssertGreaterThan(
            checked, 0,
            "no negative vectors in the corpus; the positive vectors alone cannot show anything is rejected"
        )
    }

    /// True only when the vector both decodes AND verifies -- the two steps a
    /// negative vector is allowed to fail at, without requiring three independent
    /// error vocabularies to agree on wording.
    private func decodesAndVerifies(_ decode: () throws -> Dag) -> Bool {
        do {
            try decode().verify()
            return true
        } catch {
            return false
        }
    }

    func testManifestTransmissionSequenceCBORParityAndReplay() throws {
        for vectorCase in try loadedManifest().cases {
            let receiver = Dag()

            for packetPath in vectorCase.transmissionPackets {
                let committed = try readVector(packetPath)
                let packet = try TransmissionPacket.fromCBOR(committed)

                let first = packet.toCBOR()
                let second = packet.toCBOR()

                XCTAssertEqual(
                    first, committed,
                    "\(vectorCase.name): re-encoded \(packetPath) differs from the bytes Go committed"
                )
                XCTAssertEqual(
                    first, second,
                    "\(vectorCase.name): encoding \(packetPath) twice produced different bytes"
                )

                let roundTripped = try TransmissionPacket.fromCBOR(first)
                XCTAssertEqual(roundTripped.parentHash, packet.parentHash, vectorCase.name)
                XCTAssertEqual(roundTripped.leaf.hash, packet.leaf.hash, vectorCase.name)
                XCTAssertEqual(roundTripped.leaf.links, packet.leaf.links, vectorCase.name)
                XCTAssertEqual(Set(roundTripped.proofs.keys), Set(packet.proofs.keys), vectorCase.name)
                try receiver.applyAndVerifyTransmissionPacket(roundTripped)
            }

            assertShape("\(vectorCase.name) (replayed)", receiver, vectorCase)
            try receiver.verify()
        }
    }

    func testManifestBatchedSequenceCBORParityAndReplay() throws {
        var splitCases = 0
        for vectorCase in try loadedManifest().cases {
            if vectorCase.batchedPackets.count > 1 {
                splitCases += 1
            }
            let receiver = Dag()

            for batchPath in vectorCase.batchedPackets {
                let committed = try readVector(batchPath)
                let batch = try BatchedTransmissionPacket.fromCBOR(committed)

                let first = batch.toCBOR()
                let second = batch.toCBOR()

                XCTAssertEqual(
                    first, committed,
                    "\(vectorCase.name): re-encoded \(batchPath) differs from the bytes Go committed"
                )
                XCTAssertEqual(
                    first, second,
                    "\(vectorCase.name): encoding \(batchPath) twice produced different bytes"
                )

                let roundTripped = try BatchedTransmissionPacket.fromCBOR(first)
                XCTAssertEqual(
                    roundTripped.leaves.map(\.hash), batch.leaves.map(\.hash), vectorCase.name
                )
                XCTAssertEqual(roundTripped.relationships, batch.relationships, vectorCase.name)
                try receiver.applyAndVerifyBatchedTransmissionPacket(roundTripped)
            }

            assertShape("\(vectorCase.name) (batch replayed)", receiver, vectorCase)
            try receiver.verify()
        }

        // Without this, a corpus that happened to fit every case in one batch would
        // still pass, and the batch-splitting path -- where the interesting proof
        // bugs live -- would go untested while looking tested.
        XCTAssertGreaterThan(
            splitCases, 0,
            "no case in the corpus splits across multiple batches; the batching path is untested"
        )
    }

    /// The eighth assertion, and with the ninth the newest here: for its first four
    /// releases this corpus compared CBOR only.
    ///
    /// That gap was not theoretical, and Swift is one of the two ports it hid. This
    /// port reached JSON through `Codable` while reaching CBOR through the wire
    /// tree, so the two encodings did not even agree on FIELD NAMES -- and every
    /// assertion above passed the whole time, because none of them opened a `.json`
    /// file. (Rust's failure was subtler: same names, wrong map key order, because
    /// CBOR sorts length-first and `encoding/json` sorts bytewise.)
    ///
    /// Two things are checked per artifact, and the second is the load-bearing one:
    ///
    /// 1. re-encoding the decoded value to JSON reproduces the committed JSON bytes;
    /// 2. re-encoding that SAME value to CBOR reproduces the committed CBOR bytes.
    ///
    /// (2) is what makes this more than a formatting test. It says the value this
    /// port gets out of the JSON decoder is indistinguishable from the value it gets
    /// out of the CBOR decoder -- the actual interoperability claim, and one that
    /// cannot be proved by comparing a file against itself.
    func testManifestJSONMatchesTheCommittedBytes() throws {
        var checked = 0
        for vectorCase in try loadedManifest().cases {
            XCTAssertEqual(
                vectorCase.partialDags.count, vectorCase.partialDagsJSON.count,
                "\(vectorCase.name): the manifest lists a different number of JSON and CBOR partials"
            )
            XCTAssertEqual(
                vectorCase.transmissionPackets.count, vectorCase.transmissionPacketsJSON.count,
                "\(vectorCase.name): the manifest lists a different number of JSON and CBOR packets"
            )
            XCTAssertEqual(
                vectorCase.batchedPackets.count, vectorCase.batchedPacketsJSON.count,
                "\(vectorCase.name): the manifest lists a different number of JSON and CBOR batches"
            )

            let dagCBOR = [vectorCase.fullDag] + vectorCase.partialDags
            let dagJSON = [vectorCase.fullDagJSON] + vectorCase.partialDagsJSON
            for (cborPath, jsonPath) in zip(dagCBOR, dagJSON) {
                let committed = try readVector(jsonPath)
                let dag = try Dag.fromJSON(committed)
                XCTAssertEqual(dag.root, vectorCase.rootHash, "\(vectorCase.name): \(jsonPath) root")
                try dag.verify()
                try assertJSONAndCBORAgree(
                    vectorCase.name, jsonPath, cborPath, committed,
                    dag.toJSON(), dag.toCBOR()
                )
                checked += 1
            }

            for (cborPath, jsonPath) in zip(vectorCase.transmissionPackets, vectorCase.transmissionPacketsJSON) {
                let committed = try readVector(jsonPath)
                let packet = try TransmissionPacket.fromJSON(committed)
                try assertJSONAndCBORAgree(
                    vectorCase.name, jsonPath, cborPath, committed,
                    packet.toJSON(), packet.toCBOR()
                )
                checked += 1
            }

            for (cborPath, jsonPath) in zip(vectorCase.batchedPackets, vectorCase.batchedPacketsJSON) {
                let committed = try readVector(jsonPath)
                let batch = try BatchedTransmissionPacket.fromJSON(committed)
                try assertJSONAndCBORAgree(
                    vectorCase.name, jsonPath, cborPath, committed,
                    batch.toJSON(), batch.toCBOR()
                )
                checked += 1
            }
        }

        XCTAssertGreaterThan(
            checked, 0,
            "the manifest names no JSON artifacts; this assertion would pass vacuously"
        )
    }

    private func assertJSONAndCBORAgree(
        _ name: String,
        _ jsonPath: String,
        _ cborPath: String,
        _ committedJSON: Data,
        _ reJSON: Data,
        _ reCBOR: Data
    ) throws {
        XCTAssertEqual(
            reJSON, committedJSON,
            "\(name): re-encoded \(jsonPath) differs from the JSON bytes Go committed"
        )
        let committedCBOR = try readVector(cborPath)
        XCTAssertEqual(
            reCBOR, committedCBOR,
            "\(name): \(jsonPath) decoded from JSON re-encodes to different CBOR than \(cborPath)"
        )
    }

    /// The ninth assertion: the guard on the guard.
    ///
    /// Map key order is only observable when the keys differ in LENGTH, and every
    /// map in this corpus except one is keyed by CID -- and a CID is `b` plus
    /// base32 of exactly 36 bytes, so it is exactly 59 characters, always. If
    /// `json_metadata_probe` ever lost its mixed-length metadata, every assertion
    /// above would keep passing while quietly losing the ability to fail for the
    /// reason it exists. Reordering a map preserves its encoded byte LENGTH too, so
    /// a size comparison would not have noticed either.
    func testManifestProbeCaseCanTellTheTwoSortRulesApart() throws {
        let manifest = try loadedManifest()
        guard let probe = manifest.cases.first(where: { !$0.additionalData.isEmpty }) else {
            XCTFail(
                "no case in the corpus carries additional data; nothing here can distinguish the JSON and CBOR key orders"
            )
            return
        }

        let lengths = Set(probe.additionalData.map { $0.key.utf8.count })
        XCTAssertGreaterThan(
            lengths.count, 1,
            "\(probe.name): every metadata key is the same length, and the two sort rules agree on those"
        )

        // "aaa-probe" is 9 bytes and "zz-probe" is 8, so length-first and bytewise
        // MUST place them in opposite orders. Both are unambiguous as raw substrings
        // of either encoding: this fixture's leaf content is uppercase ASCII, and a
        // base32 CID contains no "-".
        let json = try readVector(probe.fullDagJSON)
        let cbor = try readVector(probe.fullDag)
        XCTAssertLessThan(
            byteOffset(of: "aaa-probe", in: json, probe.name),
            byteOffset(of: "zz-probe", in: json, probe.name),
            "\(probe.name): the committed JSON sorted the 8-byte key first, which is CBOR's length-first rule"
        )
        XCTAssertLessThan(
            byteOffset(of: "zz-probe", in: cbor, probe.name),
            byteOffset(of: "aaa-probe", in: cbor, probe.name),
            "\(probe.name): the committed CBOR sorted the 9-byte key first, which is not RFC 8949 core-deterministic order"
        )
    }

    /// Raw byte search, so the probe assertions can talk about both encodings with
    /// one helper. A `String` search is not an option here: CBOR is not UTF-8.
    private func byteOffset(of needle: String, in data: Data, _ label: String) -> Int {
        guard let range = data.range(of: Data(needle.utf8)) else {
            XCTFail("\(label): \(needle) is missing from the committed vector")
            return Int.max
        }
        return range.lowerBound
    }
}
